const upsertOperatorCreditClawback = `-- name: UpsertOperatorCreditClawback :one
WITH existing AS (
    SELECT operator_credit_ledger_id AS id
    FROM purser.operator_credit_clawback_reversals
    WHERE payment_reversal_id = $1::text::uuid
      AND accrual_ledger_id = $2::text::uuid
), inserted AS (
    INSERT INTO purser.operator_credit_ledger (
        source_type, invoice_line_item_id, provider_usage_record_id, usage_adjustment_id,
        stripe_invoice_id, entry_type, reverses_ledger_id, cluster_owner_tenant_id,
        cluster_id, invoice_id, period_start, period_end, currency, gross_cents,
        platform_fee_cents, payable_cents, status, notes
    )
    SELECT ledger.source_type, ledger.invoice_line_item_id, ledger.provider_usage_record_id,
           ledger.usage_adjustment_id, ledger.stripe_invoice_id, 'clawback', ledger.id,
           ledger.cluster_owner_tenant_id, ledger.cluster_id, ledger.invoice_id,
           ledger.period_start, ledger.period_end, ledger.currency,
           -($3::bigint), -($4::bigint),
           -($5::bigint),
           'clawed_back', jsonb_build_object('payment_reversal_id', $1::text)
    FROM purser.operator_credit_ledger ledger
    WHERE ledger.id = $2::text::uuid
      AND NOT EXISTS (SELECT 1 FROM existing)
    RETURNING id
), chosen AS (
    SELECT id FROM existing UNION ALL SELECT id FROM inserted LIMIT 1
), mapped AS (
    INSERT INTO purser.operator_credit_clawback_reversals (
        payment_reversal_id, operator_credit_ledger_id, accrual_ledger_id
    )
    SELECT $1::text::uuid, id,
           $2::text::uuid
    FROM chosen
    ON CONFLICT (payment_reversal_id, accrual_ledger_id) DO UPDATE
    SET operator_credit_ledger_id = EXCLUDED.operator_credit_ledger_id
    RETURNING operator_credit_ledger_id
)
SELECT operator_credit_ledger_id::text AS operator_credit_ledger_id FROM mapped
`

type UpsertOperatorCreditClawbackParams struct {
	PaymentReversalID string `db:"payment_reversal_id" json:"payment_reversal_id"`
	AccrualLedgerID   string `db:"accrual_ledger_id" json:"accrual_ledger_id"`
	GrossCents        int64  `db:"gross_cents" json:"gross_cents"`
	FeeCents          int64  `db:"fee_cents" json:"fee_cents"`
	PayableCents      int64  `db:"payable_cents" json:"payable_cents"`
}

func (q *Queries) UpsertOperatorCreditClawback(ctx context.Context, arg UpsertOperatorCreditClawbackParams) (string, error) {
	row := q.db.QueryRowContext(ctx, upsertOperatorCreditClawback,
		arg.PaymentReversalID,
		arg.AccrualLedgerID,
		arg.GrossCents,
		arg.FeeCents,
		arg.PayableCents,
	)
	var operator_credit_ledger_id string
	err := row.Scan(&operator_credit_ledger_id)
	return operator_credit_ledger_id, err
}

const upsertProviderPaymentObject = `-- name: UpsertProviderPaymentObject :exec
INSERT INTO purser.provider_payment_objects (
    provider, object_type, provider_object_id, tenant_id,
    local_reference_type, local_reference_id, intent_id, metadata,
    created_at, updated_at
) VALUES (
    $1, $2, $3,
    $4::text::uuid, $5,
    $6::text::uuid, $7::text::uuid,
    $8::jsonb, NOW(), NOW()
)
ON CONFLICT (provider, object_type, provider_object_id) DO UPDATE SET
    tenant_id = COALESCE(EXCLUDED.tenant_id, purser.provider_payment_objects.tenant_id),
    local_reference_type = COALESCE(EXCLUDED.local_reference_type, purser.provider_payment_objects.local_reference_type),
    local_reference_id = COALESCE(EXCLUDED.local_reference_id, purser.provider_payment_objects.local_reference_id),
    intent_id = COALESCE(EXCLUDED.intent_id, purser.provider_payment_objects.intent_id),
    metadata = purser.provider_payment_objects.metadata || EXCLUDED.metadata,
    updated_at = NOW()
`

type UpsertProviderPaymentObjectParams struct {
	Provider           string          `db:"provider" json:"provider"`
	ObjectType         string          `db:"object_type" json:"object_type"`
	ProviderObjectID   string          `db:"provider_object_id" json:"provider_object_id"`
	TenantID           sql.NullString  `db:"tenant_id" json:"tenant_id"`
	LocalReferenceType sql.NullString  `db:"local_reference_type" json:"local_reference_type"`
	LocalReferenceID   sql.NullString  `db:"local_reference_id" json:"local_reference_id"`
	IntentID           sql.NullString  `db:"intent_id" json:"intent_id"`
	Metadata           json.RawMessage `db:"metadata" json:"metadata"`
}

func (q *Queries) UpsertProviderPaymentObject(ctx context.Context, arg UpsertProviderPaymentObjectParams) error {
	_, err := q.db.ExecContext(ctx, upsertProviderPaymentObject,
		arg.Provider,
		arg.ObjectType,
		arg.ProviderObjectID,
		arg.TenantID,
		arg.LocalReferenceType,
		arg.LocalReferenceID,
		arg.IntentID,
		arg.Metadata,
	)
	return err
}

const upsertSucceededPaymentReversal = `-- name: UpsertSucceededPaymentReversal :one
INSERT INTO purser.payment_reversals (
    tenant_id, payment_id, pending_topup_id, invoice_id,
    provider, reversal_type, provider_reversal_id, provider_charge_id,
    amount_cents, currency, status, reason
) VALUES (
    $1::text::uuid, $2::text::uuid,
    $3::text::uuid, $4::text::uuid,
    $5, $6, $7,
    $8, $9, $10,
    'succeeded', $11
)
ON CONFLICT (provider, provider_reversal_id) DO UPDATE SET
    payment_id = COALESCE(purser.payment_reversals.payment_id, EXCLUDED.payment_id),
    pending_topup_id = COALESCE(purser.payment_reversals.pending_topup_id, EXCLUDED.pending_topup_id),
    invoice_id = COALESCE(purser.payment_reversals.invoice_id, EXCLUDED.invoice_id),
    provider_charge_id = COALESCE(purser.payment_reversals.provider_charge_id, EXCLUDED.provider_charge_id),
    status = 'succeeded', updated_at = NOW()
WHERE purser.payment_reversals.status = 'pending'
RETURNING id::text AS id
`

type UpsertSucceededPaymentReversalParams struct {
	TenantID           string         `db:"tenant_id" json:"tenant_id"`
	PaymentID          sql.NullString `db:"payment_id" json:"payment_id"`
	PendingTopupID     sql.NullString `db:"pending_topup_id" json:"pending_topup_id"`
	InvoiceID          sql.NullString `db:"invoice_id" json:"invoice_id"`
	Provider           string         `db:"provider" json:"provider"`
	ReversalType       string         `db:"reversal_type" json:"reversal_type"`
	ProviderReversalID string         `db:"provider_reversal_id" json:"provider_reversal_id"`
	ProviderChargeID   sql.NullString `db:"provider_charge_id" json:"provider_charge_id"`
	AmountCents        int64          `db:"amount_cents" json:"amount_cents"`
	Currency           string         `db:"currency" json:"currency"`
	Reason             sql.NullString `db:"reason" json:"reason"`
}

func (q *Queries) UpsertSucceededPaymentReversal(ctx context.Context, arg UpsertSucceededPaymentReversalParams) (string, error) {
	row := q.db.QueryRowContext(ctx, upsertSucceededPaymentReversal,
		arg.TenantID,
		arg.PaymentID,
		arg.PendingTopupID,
		arg.InvoiceID,
		arg.Provider,
		arg.ReversalType,
		arg.ProviderReversalID,
		arg.ProviderChargeID,
		arg.AmountCents,
		arg.Currency,
		arg.Reason,
	)
	var id string
	err := row.Scan(&id)
	return id, err
}
